#!/usr/bin/env python3
"""Build portable, offline NGL views of verified conference candidates."""
import argparse,json
from pathlib import Path

HTML=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Loam · EGFR binder candidates · NGL</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f3f6f8;color:#193647;font:16px system-ui}main{max-width:1900px;padding:28px;margin:auto}h1{font-size:30px;margin:4px 0 8px}p{line-height:1.5}.controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:20px 0}button,select{font:inherit;background:white;border:1px solid #cbd6dc;padding:10px 14px;border-radius:7px;cursor:pointer}button.active{color:white;background:#147f83}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.card{background:white;border-radius:12px;overflow:hidden;border:1px solid #e0e7eb}.viewer{width:100%;height:560px;position:relative}.details{padding:16px 20px}.details h2{font-size:20px;margin:0 0 8px}.meta{color:#536b76;font-size:14px}.legend{display:flex;gap:20px;flex-wrap:wrap}.dot{width:12px;height:12px;display:inline-block;border-radius:50%;margin-right:6px}footer{font-size:13px;color:#586d78;margin-top:24px}#status{font-size:14px}a{color:#087f87}@media(max-width:950px){.cards{grid-template-columns:1fr}.viewer{height:500px}}</style>
<main><p class="meta">LOAM · 256-NODE JUPITER CAMPAIGN</p><h1>Full-context EGFR binder candidates</h1><p>Three distinct designed sequences selected from 937 follow-up trials. Minimized poses are shown; ipTM comes from the preceding Chai ensemble.</p>
<div class="controls"><button id="clean" class="active" onclick="setStyle('clean')">Clean cartoons</button><button id="interface" onclick="setStyle('interface')">Highlight interface residues</button><select id="view" aria-label="Molecular framing" onchange="setView(this.value)"><option value="site">Binding-site view</option><option value="context">Full 622-residue EGFR</option></select><button onclick="resetViews()">Reset cameras</button><label><input id="transparent" type="checkbox" checked> Transparent PNG background</label><span id="status">Loading NGL…</span></div>
<div class="legend"><span><i class="dot" style="background:#bac5ce"></i>EGFR</span><span><i class="dot" style="background:#078a92"></i>Designed binder</span><span><i class="dot" style="background:#dba83b"></i>Contact-residue carbons in highlighted view</span></div><div class="cards" id="cards"></div>
<footer>Interface: interchain heavy atoms within 4 Å; complete contacting residues are highlighted. Binding-site views display the crop-equivalent receptor domain from the full-context prediction. Chain A1–622 maps to UniProt P00533 residues25–646; chain B1–60 is the binder. Contacts in all five poses are a structural criterion, not an affinity measurement. Drag to rotate; scroll to zoom. Downloaded images preserve your current camera. All structure data and NGL are bundled locally; internet access is unnecessary.</footer></main>
<script src="vendor/ngl.js"></script><script>const candidates=__CANDIDATES__;
window.stages=[];window.components=[];window.currentStyle='clean';window.currentView='site';window.errors=[];
function selection(ids,chain){return '('+ids.map(n=>n+':'+chain).join(' or ')+')'}
function contactColor(carbon){return NGL.ColormakerRegistry.addScheme(function(){this.atomColor=function(atom){if(atom.element==='O')return 0xd54e45;if(atom.element==='N')return 0x3b60ba;if(atom.element==='S')return 0xcaa433;return carbon}})}
async function draw(i){const c=candidates[i],o=components[i],s=stages[i];o.removeAllRepresentations();const receptor=currentView==='site'?':A and 286-490':':A';const receptorColor=currentStyle==='interface'?NGL.ColormakerRegistry.addSelectionScheme([['#dba83b',selection(c.interface_target_residues,'A')],['#b6c1ca','*']]):'#b6c1ca';o.addRepresentation('cartoon',{sele:receptor,color:receptorColor,opacity:.85,aspectRatio:4,quality:'high'});o.addRepresentation('surface',{sele:receptor,color:'#c1cbd2',opacity:currentStyle==='interface'?.07:.16,surfaceType:'av',probeRadius:1.4,useWorker:false,quality:'medium'});o.addRepresentation('cartoon',{sele:':B',color:c.color,aspectRatio:5,radiusScale:1.1,quality:'high'});
if(currentStyle==='interface'){o.addRepresentation('licorice',{sele:selection(c.interface_target_residues,'A')+' and sidechain and not _H',colorScheme:contactColor(0xdba83b),radius:.22,radiusScale:1,quality:'high'});o.addRepresentation('licorice',{sele:selection(c.interface_binder_residues,'B')+' and sidechain and not _H',colorScheme:contactColor(parseInt(c.color.slice(1),16)),radius:.22,radiusScale:1,quality:'high'})}
return new Promise(resolve=>s.tasks.onZeroOnce(resolve));}
async function resetViews(){for(let i=0;i<components.length;i++){components[i].autoView(currentView==='site'?'(:A and 286-490) or :B':':A or :B',0);stages[i].viewerControls.zoom(-.12)}return true}
async function setStyle(style){currentStyle=style;document.getElementById('clean').classList.toggle('active',style==='clean');document.getElementById('interface').classList.toggle('active',style==='interface');await Promise.all(components.map((_,i)=>draw(i)));document.getElementById('status').textContent='Ready · '+style;return true}
async function setView(view){currentView=view;document.getElementById('view').value=view;await Promise.all(components.map((_,i)=>draw(i)));await resetViews();return true}
async function imageBlob(i,transparent=false,factor=3){return stages[i].makeImage({factor,antialias:true,trim:true,transparent})}
async function exportPNG(i){try{const blob=await imageBlob(i,document.getElementById('transparent').checked);NGL.download(blob,candidates[i].id+'-'+currentStyle+'-'+currentView+(document.getElementById('transparent').checked?'-transparent':'')+'.png')}catch(e){errors.push(String(e));document.getElementById('status').textContent=String(e)}}
window.imageData=async function(i,transparent=false){const blob=await imageBlob(i,transparent,3);return await new Promise(resolve=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.readAsDataURL(blob)})};
window.ready=(async()=>{if(!window.NGL)throw Error('Bundled NGL could not load');document.getElementById('cards').innerHTML=candidates.map((c,i)=>`<section class="card"><div class="viewer" id="v${i}"></div><div class="details"><h2 style="color:${c.color}">${c.label}</h2><p>Best Chai ipTM <b>${c.intact_iptm_best.toFixed(3)}</b> · both-region contacts <b>${c.intact_models_with_dual_region_contact}/5 poses</b></p><p class="meta">${c.condition.replaceAll('_',' ')} conditioning · minimized binder pose shift ${c.minimized_binder_RMSD_A.toFixed(2)} Å<br>Static MM/GBSA ${c.static_MMGBSA_kcal_mol.toFixed(1)} kcal/mol; entropy omitted</p><button onclick="exportPNG(${i})">Download high-resolution PNG</button></div></section>`).join('');
for(let i=0;i<candidates.length;i++){const stage=new NGL.Stage('v'+i,{backgroundColor:'white',cameraType:'orthographic',quality:'high',sampleLevel:1,lightIntensity:.9,ambientIntensity:.45});stages.push(stage);const o=await stage.loadFile(new Blob([candidates[i].pdb],{type:'text/plain'}),{ext:'pdb',defaultRepresentation:false});components.push(o);await draw(i)}await resetViews();window.addEventListener('resize',()=>stages.forEach(s=>s.handleResize()));document.getElementById('status').textContent='Ready · clean';window.renderReady=true;return true})().catch(e=>{errors.push(String(e));document.getElementById('status').textContent=String(e);throw e});</script></html>'''

def main(out):
    data=json.loads((out/'science-data.json').read_text());keys=['id','label','color','pdb','condition','interface_target_residues','interface_binder_residues','intact_iptm_best','intact_models_with_dual_region_contact','minimized_binder_RMSD_A','static_MMGBSA_kcal_mol']
    values=[{k:c[k] for k in keys} for c in data['top_binders']];(out/'ngl-gallery.html').write_text(HTML.replace('__CANDIDATES__',json.dumps(values).replace('</','<\\/')))
    print(out/'ngl-gallery.html')

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('output',type=Path);a=p.parse_args();main(a.output.resolve())
